57	  const calls = getCalls();
58	  const { callSessionRef } = await calls.createSession({
59	    bookingId,
60	    providerId: booking.provider_id,
61	    customerId: booking.customer_id,
62	    maxMinutes: booking.block_minutes + 15,
63	  });
64	
65	  const admin = createAdminClient();
66	  const { data: session, error } = await admin
67	    .from("sessions")
68	    .insert({
69	      booking_id: bookingId,
70	      provider_id: booking.provider_id,
71	      customer_id: booking.customer_id,
72	      call_session_ref: callSessionRef,
73	      started_at: new Date().toISOString(),
74	      block_minutes: booking.block_minutes,
75	      status: "in_progress",
76	    })
77	    .select("id")
78	    .single();
79	  if (error || !session) return { error: "We couldn't start the call." };
